INSERT INTO skill_runtime_memories (id, skill_id, data_source_id, type, `key`, content, confidence, source, `status`, last_used_at, created_at, updated_at) VALUES ('8c47268b-faea-4454-9536-cb2cb0686921', '50d894de-9df0-466f-a3e5-164e3502db7a', '1cce62ad-7c32-4179-8b2b-581f0edd1e87', 'text2sql_template', 'employee_monthly_sales_value', '{"intent":"出单价值","SQLTemplate":"SELECT DATE_FORMAT(t_order.delivery_time, ''%Y-%m'') AS month, SUM(t_order_amount.amount) AS sales_amount FROM t_order JOIN t_profile ON t_order.sale_staff_id = t_profile.user_id JOIN t_order_amount ON t_order_amount.order_id = t_order.id WHERE t_profile.real_name = {{employee_name}} AND t_order.delivery_time >= {{start_date}} AND t_order.delivery_time < {{end_date}} AND t_order.delivery_time IS NOT NULL AND t_order.order_status != 0 AND t_order_amount.fee_code = ''sub_total'' GROUP BY month ORDER BY month"}', 0.96, 'admin', 'active', NOW(), NOW(), NOW()) ON DUPLICATE KEY UPDATE content='{"intent":"出单价值","SQLTemplate":"SELECT DATE_FORMAT(t_order.delivery_time, ''%Y-%m'') AS month, SUM(t_order_amount.amount) AS sales_amount FROM t_order JOIN t_profile ON t_order.sale_staff_id = t_profile.user_id JOIN t_order_amount ON t_order_amount.order_id = t_order.id WHERE t_profile.real_name = {{employee_name}} AND t_order.delivery_time >= {{start_date}} AND t_order.delivery_time < {{end_date}} AND t_order.delivery_time IS NOT NULL AND t_order.order_status != 0 AND t_order_amount.fee_code = ''sub_total'' GROUP BY month ORDER BY month"}', confidence=0.96, source='admin', `status`='active', updated_at=NOW();
INSERT INTO skill_runtime_memories (id, skill_id, data_source_id, type, `key`, content, confidence, source, `status`, last_used_at, created_at, updated_at) VALUES ('4883ca69-0172-4736-bc29-29b9b4979297', '50d894de-9df0-466f-a3e5-164e3502db7a', '1cce62ad-7c32-4179-8b2b-581f0edd1e87', 'text2sql_template', 'employee_monthly_profit', '{"SQLTemplate":"SELECT DATE_FORMAT(t_order.delivery_time, ''%Y-%m'') AS month, SUM(t_order_sales_profit.qty*(t_order_sales_profit.sale_price-t_order_sales_profit.purchase_price)) AS profit FROM t_order JOIN t_profile ON t_order.sale_staff_id=t_profile.user_id JOIN t_order_sales_profit ON t_order_sales_profit.order_id=t_order.id WHERE t_profile.real_name={{employee_name}} AND t_order.delivery_time \u003e= {{start_date}} AND t_order.delivery_time \u003c {{end_date}} AND t_order.delivery_time IS NOT NULL AND t_order.order_status != 0 GROUP BY month ORDER BY month","intent":"利润,毛利,赚了多少,利润多少"}', 0.97, 'admin', 'active', NOW(), NOW(), NOW()) ON DUPLICATE KEY UPDATE content='{"SQLTemplate":"SELECT DATE_FORMAT(t_order.delivery_time, ''%Y-%m'') AS month, SUM(t_order_sales_profit.qty*(t_order_sales_profit.sale_price-t_order_sales_profit.purchase_price)) AS profit FROM t_order JOIN t_profile ON t_order.sale_staff_id=t_profile.user_id JOIN t_order_sales_profit ON t_order_sales_profit.order_id=t_order.id WHERE t_profile.real_name={{employee_name}} AND t_order.delivery_time \u003e= {{start_date}} AND t_order.delivery_time \u003c {{end_date}} AND t_order.delivery_time IS NOT NULL AND t_order.order_status != 0 GROUP BY month ORDER BY month","intent":"利润,毛利,赚了多少,利润多少"}', confidence=0.97, source='admin', `status`='active', updated_at=NOW();
