INSERT INTO skill_runtime_memories (id, skill_id, data_source_id, type, `key`, content, confidence, source, `status`, last_used_at, created_at, updated_at) VALUES ('8d48a515-a5e7-4f84-a3d7-c7084c2415d1', '50d894de-9df0-466f-a3e5-164e3502db7a', '1cce62ad-7c32-4179-8b2b-581f0edd1e87', 'text2sql_template', 'sku_sales_analysis', '{"intent":"sku","SQLTemplate":"SELECT COALESCE(t_item.shop_sku,t_item.shop_sku_id,t_order_item.sku_id) AS sku, COALESCE(t_item.title,''未知产品'') AS title, COUNT(DISTINCT t_order.id) AS order_count, SUM(t_order_item.quantity) AS quantity, SUM(t_order_item.price*t_order_item.quantity) AS item_sales_amount FROM t_order JOIN t_order_item ON t_order_item.order_id=t_order.id LEFT JOIN t_item ON t_order_item.sku_id=t_item.id WHERE t_order.delivery_time >= {{start_date}} AND t_order.delivery_time < {{end_date}} AND t_order.delivery_time IS NOT NULL AND t_order.order_status != 0 GROUP BY sku,title ORDER BY item_sales_amount DESC LIMIT 50"}', 0.97, 'admin', 'active', NOW(), NOW(), NOW()) ON DUPLICATE KEY UPDATE content='{"intent":"sku","SQLTemplate":"SELECT COALESCE(t_item.shop_sku,t_item.shop_sku_id,t_order_item.sku_id) AS sku, COALESCE(t_item.title,''未知产品'') AS title, COUNT(DISTINCT t_order.id) AS order_count, SUM(t_order_item.quantity) AS quantity, SUM(t_order_item.price*t_order_item.quantity) AS item_sales_amount FROM t_order JOIN t_order_item ON t_order_item.order_id=t_order.id LEFT JOIN t_item ON t_order_item.sku_id=t_item.id WHERE t_order.delivery_time >= {{start_date}} AND t_order.delivery_time < {{end_date}} AND t_order.delivery_time IS NOT NULL AND t_order.order_status != 0 GROUP BY sku,title ORDER BY item_sales_amount DESC LIMIT 50"}', confidence=0.97, source='admin', `status`='active', updated_at=NOW();
INSERT INTO skill_runtime_memories (id, skill_id, data_source_id, type, `key`, content, confidence, source, `status`, last_used_at, created_at, updated_at) VALUES ('67aaa6c1-3a4e-45a7-950b-71e06fa7ed26', '50d894de-9df0-466f-a3e5-164e3502db7a', '1cce62ad-7c32-4179-8b2b-581f0edd1e87', 'text2sql_template', 'sku_profit_analysis', '{"intent":"sku利润","SQLTemplate":"SELECT COALESCE(t_item.shop_sku,t_item.shop_sku_id,t_order_sales_profit.sku_id) AS sku, COALESCE(t_item.title,''未知产品'') AS title, SUM(t_order_sales_profit.qty) AS quantity, SUM(t_order_sales_profit.qty*t_order_sales_profit.sale_price) AS sales_amount, SUM(t_order_sales_profit.qty*t_order_sales_profit.purchase_price) AS cost_amount, SUM(t_order_sales_profit.qty*(t_order_sales_profit.sale_price-t_order_sales_profit.purchase_price)) AS gross_profit FROM t_order_sales_profit JOIN t_order ON t_order_sales_profit.order_id=t_order.id LEFT JOIN t_item ON t_order_sales_profit.sku_id=t_item.id WHERE t_order.delivery_time >= {{start_date}} AND t_order.delivery_time < {{end_date}} AND t_order.delivery_time IS NOT NULL AND t_order.order_status != 0 GROUP BY sku,title ORDER BY gross_profit DESC LIMIT 50"}', 0.97, 'admin', 'active', NOW(), NOW(), NOW()) ON DUPLICATE KEY UPDATE content='{"intent":"sku利润","SQLTemplate":"SELECT COALESCE(t_item.shop_sku,t_item.shop_sku_id,t_order_sales_profit.sku_id) AS sku, COALESCE(t_item.title,''未知产品'') AS title, SUM(t_order_sales_profit.qty) AS quantity, SUM(t_order_sales_profit.qty*t_order_sales_profit.sale_price) AS sales_amount, SUM(t_order_sales_profit.qty*t_order_sales_profit.purchase_price) AS cost_amount, SUM(t_order_sales_profit.qty*(t_order_sales_profit.sale_price-t_order_sales_profit.purchase_price)) AS gross_profit FROM t_order_sales_profit JOIN t_order ON t_order_sales_profit.order_id=t_order.id LEFT JOIN t_item ON t_order_sales_profit.sku_id=t_item.id WHERE t_order.delivery_time >= {{start_date}} AND t_order.delivery_time < {{end_date}} AND t_order.delivery_time IS NOT NULL AND t_order.order_status != 0 GROUP BY sku,title ORDER BY gross_profit DESC LIMIT 50"}', confidence=0.97, source='admin', `status`='active', updated_at=NOW();
INSERT INTO skill_runtime_memories (id, skill_id, data_source_id, type, `key`, content, confidence, source, `status`, last_used_at, created_at, updated_at) VALUES ('663b6bea-913f-4448-b29b-c4b9e5ab18ff', 'b1a08fcd-0a21-4a42-b2d7-e7f5549bd9cf', '1cce62ad-7c32-4179-8b2b-581f0edd1e87', 'text2sql_template', 'customer_contribution_rank', '{"intent":"客户","SQLTemplate":"SELECT COALESCE(t_member.company_name,t_member.name,''未知客户'') AS customer, COUNT(DISTINCT t_order.id) AS orders, SUM(t_order_amount.amount) AS sales FROM t_order JOIN t_order_amount ON t_order_amount.order_id=t_order.id LEFT JOIN t_member ON t_order.vip_id=t_member.id WHERE t_order.delivery_time >= {{start_date}} AND t_order.delivery_time < {{end_date}} AND t_order.delivery_time IS NOT NULL AND t_order.order_status != 0 AND t_order_amount.fee_code=''sub_total'' GROUP BY customer ORDER BY sales DESC LIMIT 20"}', 0.98, 'admin', 'active', NOW(), NOW(), NOW()) ON DUPLICATE KEY UPDATE content='{"intent":"客户","SQLTemplate":"SELECT COALESCE(t_member.company_name,t_member.name,''未知客户'') AS customer, COUNT(DISTINCT t_order.id) AS orders, SUM(t_order_amount.amount) AS sales FROM t_order JOIN t_order_amount ON t_order_amount.order_id=t_order.id LEFT JOIN t_member ON t_order.vip_id=t_member.id WHERE t_order.delivery_time >= {{start_date}} AND t_order.delivery_time < {{end_date}} AND t_order.delivery_time IS NOT NULL AND t_order.order_status != 0 AND t_order_amount.fee_code=''sub_total'' GROUP BY customer ORDER BY sales DESC LIMIT 20"}', confidence=0.98, source='admin', `status`='active', updated_at=NOW();
INSERT INTO skill_runtime_memories (id, skill_id, data_source_id, type, `key`, content, confidence, source, `status`, last_used_at, created_at, updated_at) VALUES ('0f9aaa9a-797c-4214-bbf0-4ae263c9837b', 'b1a08fcd-0a21-4a42-b2d7-e7f5549bd9cf', '1cce62ad-7c32-4179-8b2b-581f0edd1e87', 'text2sql_template', 'inventory_purchase_supply_chain', '{"intent":"库存","SQLTemplate":"SELECT ''supplier'' AS type, COALESCE(t_supplier.name,t_supplier.company_name,''未知供应商'') AS name, SUM(t_purchase_item.quantity) AS qty FROM t_purchase_item JOIN t_purchase ON t_purchase_item.purchase_id=t_purchase.id LEFT JOIN t_supplier ON t_purchase.supplier_id=t_supplier.id WHERE t_purchase.created_at >= {{start_date}} AND t_purchase.created_at < {{end_date}} GROUP BY name ORDER BY qty DESC LIMIT 20"}', 0.98, 'admin', 'active', NOW(), NOW(), NOW()) ON DUPLICATE KEY UPDATE content='{"intent":"库存","SQLTemplate":"SELECT ''supplier'' AS type, COALESCE(t_supplier.name,t_supplier.company_name,''未知供应商'') AS name, SUM(t_purchase_item.quantity) AS qty FROM t_purchase_item JOIN t_purchase ON t_purchase_item.purchase_id=t_purchase.id LEFT JOIN t_supplier ON t_purchase.supplier_id=t_supplier.id WHERE t_purchase.created_at >= {{start_date}} AND t_purchase.created_at < {{end_date}} GROUP BY name ORDER BY qty DESC LIMIT 20"}', confidence=0.98, source='admin', `status`='active', updated_at=NOW();
INSERT INTO skill_runtime_memories (id, skill_id, data_source_id, type, `key`, content, confidence, source, `status`, last_used_at, created_at, updated_at) VALUES ('11642ead-6300-400a-b44c-3ea8fbb165e2', 'b1a08fcd-0a21-4a42-b2d7-e7f5549bd9cf', '1cce62ad-7c32-4179-8b2b-581f0edd1e87', 'text2sql_template', 'monthly_sales_profit_overview', '{"intent":"经营分析","SQLTemplate":"SELECT DATE_FORMAT(t_order.delivery_time,''%Y-%m'') AS month, COUNT(DISTINCT t_order.id) AS orders, SUM(t_order_amount.amount) AS sales, SUM(t_order_sales_profit.qty*(t_order_sales_profit.sale_price-t_order_sales_profit.purchase_price)) AS profit FROM t_order JOIN t_order_amount ON t_order_amount.order_id=t_order.id LEFT JOIN t_order_sales_profit ON t_order_sales_profit.order_id=t_order.id WHERE t_order.delivery_time >= {{start_date}} AND t_order.delivery_time < {{end_date}} AND t_order.delivery_time IS NOT NULL AND t_order.order_status != 0 AND t_order_amount.fee_code=''sub_total'' GROUP BY month ORDER BY month"}', 0.98, 'admin', 'active', NOW(), NOW(), NOW()) ON DUPLICATE KEY UPDATE content='{"intent":"经营分析","SQLTemplate":"SELECT DATE_FORMAT(t_order.delivery_time,''%Y-%m'') AS month, COUNT(DISTINCT t_order.id) AS orders, SUM(t_order_amount.amount) AS sales, SUM(t_order_sales_profit.qty*(t_order_sales_profit.sale_price-t_order_sales_profit.purchase_price)) AS profit FROM t_order JOIN t_order_amount ON t_order_amount.order_id=t_order.id LEFT JOIN t_order_sales_profit ON t_order_sales_profit.order_id=t_order.id WHERE t_order.delivery_time >= {{start_date}} AND t_order.delivery_time < {{end_date}} AND t_order.delivery_time IS NOT NULL AND t_order.order_status != 0 AND t_order_amount.fee_code=''sub_total'' GROUP BY month ORDER BY month"}', confidence=0.98, source='admin', `status`='active', updated_at=NOW();
